def solve(inputs: dict) -> float:
    n = inputs.get('n', inputs.get('people', inputs.get('N')))
    k = inputs.get('k', inputs.get('step', inputs.get('every')))
    if n is None or k is None:
        vals = [int(v) for v in inputs.values() if isinstance(v, (int, float))]
        n, k = vals[0], vals[1]
    n = int(n); k = int(k)
    res = 0
    for i in range(2, n + 1):
        res = (res + k) % i
    return float(res + 1)

